<template>
  <div class="merchant-page" v-loading="loading">
    <template v-if="merchant">
      <nav class="crumb"><router-link to="/market/merchants">合作商户</router-link><span>/</span><b>{{ merchant.name }}</b></nav>
      <section class="merchant-hero cpu-card">
        <div class="gallery"><img v-if="activeImage" :src="activeImage" :alt="merchant.name" /><span v-else>🏪</span><div v-if="merchant.images.length>1"><button v-for="image in merchant.images" :key="image" :class="{active:image===activeImage}" @click="activeImage=image"><img :src="image" alt="服务图片" /></button></div></div>
        <div class="summary">
          <div class="labels"><PromotionLabel v-if="merchant.promotion.promoted" label="合作商户" kind="merchant" /><el-tag v-else-if="merchant.mine" :type="statusType">{{ statusLabel }}</el-tag><span>{{ merchant.category }}</span></div>
          <h1>{{ merchant.name }}</h1><p>{{ merchant.description }}</p>
          <dl><div><dt>价格范围</dt><dd>{{ merchant.priceRange }}</dd></div><div><dt>服务范围</dt><dd>{{ merchant.serviceArea }}</dd></div><div v-if="merchant.studentDiscount"><dt>学生优惠</dt><dd>{{ merchant.studentDiscount }}</dd></div><div><dt>业务联系</dt><dd>{{ merchant.contactValueMasked }}</dd></div></dl>
          <div class="actions"><el-button :loading="favoriteLoading" :disabled="merchant.mine" @click="favorite">{{ merchant.favorited?'已收藏':'收藏商户' }}</el-button><el-button type="primary" :loading="inquiryLoading" :disabled="merchant.mine||!merchant.promotion.promoted" @click="inquire">咨询服务</el-button><el-button @click="shareOpen=true">分享</el-button></div>
          <el-alert type="info" :closable="false" title="这是明确标注的合作商户推广主页，不代表 XJTLU 官方背书。服务内容与价格请在联系后再次确认。" />
        </div>
      </section>

      <section class="content-grid">
        <article class="cpu-card service-copy"><span>SERVICE DETAILS</span><h2>服务介绍</h2><p>{{ merchant.description }}</p><div v-if="merchant.studentDiscount" class="discount"><b>学生优惠</b><span>{{ merchant.studentDiscount }}</span></div></article>
        <aside class="cpu-card provider-card"><div><UserAvatar :size="50" :src="merchant.user.avatar" :name="merchant.user.nickname" /><span><b>{{ merchant.user.nickname }}</b><small>✓ XJTLU 校园身份关联服务者</small></span></div><dl><div><b>{{ merchant.viewCount }}</b><span>浏览</span></div><div><b>{{ merchant.favoriteCount }}</b><span>收藏</span></div><div><b>{{ merchant.inquiryCount }}</b><span>咨询</span></div></dl><el-button v-if="canReport" type="danger" plain @click="reportOpen=true">举报商户</el-button><el-button v-if="merchant.mine" @click="$router.push('/market/merchant/apply')">编辑资料</el-button></aside>
      </section>

      <section class="reviews cpu-card"><header><div><span>REAL REVIEWS</span><h2>关联用户的真实交易评价</h2></div><small>仅展示靠浦内已完成交易产生的评价，不使用伪造商户评分</small></header><div v-if="reviews.length"><article v-for="review in reviews" :key="review.id"><el-rate :model-value="review.rating" disabled /><p>{{ review.content || '该用户未填写文字评价' }}</p><time>{{ formatDate(review.createdAt) }}</time></article></div><el-empty v-else :image-size="60" description="暂无可展示的真实交易评价" /></section>
    </template>
    <el-empty v-else-if="!loading" description="商户主页不存在、尚未启用或已到期"><el-button @click="$router.push('/market/merchants')">返回合作商户</el-button></el-empty>
    <el-dialog v-model="contactOpen" title="业务联系方式" width="420px"><el-alert type="warning" :closable="false" title="请先确认服务内容、价格和交付范围；不要提供验证码、学校密码等敏感信息。" /><div class="contact-value"><span>{{ contact.method }}</span><b>{{ contact.value }}</b><el-button size="small" @click="copyContact">复制</el-button></div></el-dialog>
    <el-dialog v-model="reportOpen" title="举报商户" width="440px"><el-form label-position="top"><el-form-item label="举报原因"><el-input v-model="report.reason" maxlength="80" /></el-form-item><el-form-item label="补充说明"><el-input v-model="report.detail" type="textarea" :rows="4" maxlength="1000" show-word-limit /></el-form-item></el-form><template #footer><el-button @click="reportOpen=false">取消</el-button><el-button type="danger" :loading="submitting" @click="submitReport">提交举报</el-button></template></el-dialog>
    <MarketShareDialog v-model="shareOpen" :title="merchant?.name||'合作商户'" :summary="merchant?`${merchant.category} · ${merchant.priceRange}`:''" />
  </div>
</template>

<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from "vue";
import { useRoute, useRouter } from "vue-router";
import { ElMessage } from "element-plus";
import { marketApi, type MerchantProfile } from "@/api/market";
import { useAuthStore } from "@/stores/auth";
import PromotionLabel from "@/components/market/PromotionLabel.vue";
import UserAvatar from "@/components/common/UserAvatar.vue";
import MarketShareDialog from "@/components/market/MarketShareDialog.vue";
const route=useRoute(),router=useRouter(),auth=useAuthStore();const merchant=ref<MerchantProfile|null>(null),reviews=ref<any[]>([]),loading=ref(false),submitting=ref(false),favoriteLoading=ref(false),inquiryLoading=ref(false),activeImage=ref(""),contactOpen=ref(false),shareOpen=ref(false),reportOpen=ref(false);const contact=reactive({method:"",value:""}),report=reactive({reason:"",detail:""});
const canReport=computed(()=>auth.isLoggedIn&&auth.user?.id!==merchant.value?.userId);const statusLabel=computed(()=>({reviewing:"审核中",approved:"已审核",rejected:"未通过",suspended:"已暂停"} as const)[merchant.value?.status||"reviewing"]);const statusType=computed(()=>merchant.value?.status==="approved"?"success":merchant.value?.status==="reviewing"?"warning":"danger");onMounted(load);watch(()=>route.params.slug,load);
async function load(){loading.value=true;try{const next=await marketApi.merchant(String(route.params.slug),{suppressErrorMessage:true});merchant.value=next;activeImage.value=next.images[0]||"";const result=await marketApi.reviews(next.userId,{suppressErrorMessage:true}).catch(()=>({list:[]} as any));reviews.value=result.list?.slice(0,8)||[];const orderId=next.promotion.homepage?.orderId;if(orderId)void marketApi.recordPromotionEvent(orderId,"impression",{suppressErrorMessage:true});}catch{merchant.value=null;reviews.value=[]}finally{loading.value=false}}
function requireLogin(){if(auth.isLoggedIn)return true;void router.push({name:"login",query:{redirect:route.fullPath}});return false}
async function favorite(){if(!merchant.value||!requireLogin()||favoriteLoading.value)return;favoriteLoading.value=true;try{const result=await marketApi.favoriteMerchant(merchant.value.slug);merchant.value.favorited=result.favorited;merchant.value.favoriteCount=result.favoriteCount;}finally{favoriteLoading.value=false}}
async function inquire(){if(!merchant.value||!requireLogin()||inquiryLoading.value)return;inquiryLoading.value=true;try{const result=await marketApi.inquireMerchant(merchant.value.slug);Object.assign(contact,{method:result.method,value:result.value});contactOpen.value=true;merchant.value.inquiryCount=result.inquiryCount;const orderId=merchant.value.promotion.homepage?.orderId;if(orderId)void marketApi.recordPromotionEvent(orderId,"click",{suppressErrorMessage:true});}finally{inquiryLoading.value=false}}
async function copyContact(){await navigator.clipboard.writeText(contact.value).catch(()=>null);ElMessage.success("联系方式已复制")}
async function submitReport(){if(!merchant.value||report.reason.trim().length<2)return ElMessage.warning("请填写举报原因");submitting.value=true;try{await marketApi.reportUser(merchant.value.userId,report);reportOpen.value=false;ElMessage.success("举报已提交，管理员会核查商户资料与推广记录")}finally{submitting.value=false}}
function formatDate(value:string){return new Date(value).toLocaleDateString("zh-CN")}
</script>

<style scoped>
.merchant-page{display:flex;flex-direction:column;gap:17px}.crumb{display:flex;gap:7px;color:var(--cpu-text-secondary);font-size:10px}.crumb a{color:var(--cpu-primary)}.merchant-hero{display:grid;grid-template-columns:minmax(0,1fr) minmax(360px,.9fr);gap:30px;padding:26px}.gallery>img,.gallery>span{display:grid;place-items:center;width:100%;aspect-ratio:1.35/1;object-fit:cover;border-radius:14px;background:var(--cpu-surface-soft);font-size:72px}.gallery>div{display:flex;gap:7px;margin-top:8px;overflow:auto}.gallery button{width:64px;height:54px;padding:2px;border:1px solid transparent;border-radius:8px;background:none}.gallery button.active{border-color:var(--cpu-primary)}.gallery button img{width:100%;height:100%;object-fit:cover;border-radius:5px}.labels{display:flex;align-items:center;gap:7px}.labels>span:last-child{color:var(--cpu-primary);font-size:10px}.summary h1{margin:15px 0 8px;font-size:28px}.summary>p{display:-webkit-box;overflow:hidden;color:var(--cpu-text-secondary);line-height:1.8;-webkit-box-orient:vertical;-webkit-line-clamp:3}.summary dl{display:grid;grid-template-columns:1fr 1fr;gap:7px}.summary dl>div{padding:10px;border-radius:8px;background:var(--cpu-surface-soft)}.summary dt{color:var(--cpu-text-secondary);font-size:9px}.summary dd{margin:4px 0 0;font-size:11px;font-weight:700}.actions{display:flex;gap:7px;margin:15px 0}.content-grid{display:grid;grid-template-columns:minmax(0,1fr) 310px;gap:16px}.service-copy,.provider-card,.reviews{padding:22px}.service-copy>span,.reviews header span{color:var(--cpu-primary);font-size:8px;font-weight:800;letter-spacing:.16em}.service-copy h2,.reviews h2{margin:5px 0 15px}.service-copy>p{white-space:pre-wrap;line-height:1.9}.discount{display:flex;gap:10px;padding:12px;border-radius:9px;background:#ecfdf5;color:#0f766e}.provider-card>div:first-child{display:flex;align-items:center;gap:10px}.provider-card>div:first-child span{display:flex;flex-direction:column}.provider-card small{color:var(--cpu-primary);font-size:9px}.provider-card dl{display:grid;grid-template-columns:repeat(3,1fr);margin:18px 0}.provider-card dl>div{display:flex;align-items:center;flex-direction:column}.provider-card dl span{color:var(--cpu-text-secondary);font-size:9px}.provider-card .el-button{width:100%;margin:4px 0}.reviews header{display:flex;align-items:flex-end;justify-content:space-between}.reviews header small{color:var(--cpu-text-secondary)}.reviews article{position:relative;padding:12px 0;border-top:1px solid var(--cpu-border-soft)}.reviews article p{margin:5px 80px 0 0}.reviews article time{position:absolute;right:0;top:15px;color:var(--cpu-text-muted);font-size:9px}.contact-value{display:flex;align-items:center;gap:8px;margin-top:14px;padding:13px;border-radius:9px;background:var(--cpu-surface-soft)}.contact-value b{flex:1}@media(max-width:820px){.merchant-hero,.content-grid{grid-template-columns:1fr}}@media(max-width:560px){.merchant-hero{padding:16px}.summary dl{grid-template-columns:1fr}.actions{flex-wrap:wrap}.actions .el-button{flex:1}.reviews header{align-items:flex-start;flex-direction:column;gap:5px}}
</style>
